  n bigint; s text; fp text; aud_max bigint; first_award bigint;
BEGIN
  -- PRE gates: list text
  IF md5(e) <> '649bc5cac8d589e0b04ddae153853160' OR md5(a) <> '0fe148ab4da46ca5497423b824785f4d' OR md5(j) <> '61b2f5e16177212999818008c7de894d' THEN RAISE EXCEPTION 'list text'; END IF;
  IF (SELECT count(*) FROM (SELECT 've_'||split_part(x,':',2) AS venue_id, split_part(x,':',1)::int AS rank, 'https://www.oadguides.com/lists/'||l||'/top-restaurants/2026' AS url FROM (SELECT 'europe' l, unnest(string_to_array(e,',')) x UNION ALL SELECT 'asia', unnest(string_to_array(a,',')) UNION ALL SELECT 'japan', unnest(string_to_array(j,','))) z) p) <> 1794 OR (SELECT count(DISTINCT venue_id) FROM (SELECT 've_'||split_part(x,':',2) AS venue_id, split_part(x,':',1)::int AS rank, 'https://www.oadguides.com/lists/'||l||'/top-restaurants/2026' AS url FROM (SELECT 'europe' l, unnest(string_to_array(e,',')) x UNION ALL SELECT 'asia', unnest(string_to_array(a,',')) UNION ALL SELECT 'japan', unnest(string_to_array(j,','))) z) p) <> 1789 THEN RAISE EXCEPTION 'plan rows'; END IF;
  SELECT md5(string_agg(venue_id||'|'||rank||'|'||url, E'\n' ORDER BY venue_id||'|'||rank||'|'||url COLLATE "C")) INTO fp FROM (SELECT 've_'||split_part(x,':',2) AS venue_id, split_part(x,':',1)::int AS rank, 'https://www.oadguides.com/lists/'||l||'/top-restaurants/2026' AS url FROM (SELECT 'europe' l, unnest(string_to_array(e,',')) x UNION ALL SELECT 'asia', unnest(string_to_array(a,',')) UNION ALL SELECT 'japan', unnest(string_to_array(j,','))) z) p;
  IF fp <> '4ef72925a3d80fc2292ccd9e0c620aaa' THEN RAISE EXCEPTION 'row fingerprint %', fp; END IF;
  SELECT md5(string_agg(v.id||'|'||v.name||'|'||v.status||'|'||v.city_id, E'\n' ORDER BY v.id COLLATE "C")) INTO fp FROM venues v WHERE v.id IN (SELECT venue_id FROM (SELECT 've_'||split_part(x,':',2) AS venue_id, split_part(x,':',1)::int AS rank, 'https://www.oadguides.com/lists/'||l||'/top-restaurants/2026' AS url FROM (SELECT 'europe' l, unnest(string_to_array(e,',')) x UNION ALL SELECT 'asia', unnest(string_to_array(a,',')) UNION ALL SELECT 'japan', unnest(string_to_array(j,','))) z) p);
  IF fp IS DISTINCT FROM '0caaf5e8565e59ee1420f804f24c8674' THEN RAISE EXCEPTION 'venue fingerprint %', fp; END IF;
  -- PRE gates: live state
  IF (SELECT count(*) FROM venues) <> 11336 OR (SELECT count(*) FROM venues WHERE status='active') <> 11042 OR (SELECT count(*) FROM venues WHERE status='closed') <> 294 THEN RAISE EXCEPTION 'venues before'; END IF;
  IF (SELECT count(*) FROM awards) <> 25324 OR (SELECT count(*) FROM awards WHERE source_id='oad' AND year=2026) <> 702 THEN RAISE EXCEPTION 'awards before'; END IF;
  IF (SELECT count(*) FROM slugs) <> 13184 OR (SELECT count(*) FROM listings) <> 11336 OR (SELECT count(*) FROM price) <> 7759 OR (SELECT count(*) FROM redirects) <> 13 OR (SELECT count(*) FROM city_aliases) <> 222 OR (SELECT sum(venues_count) FROM cities) <> 11042 THEN RAISE EXCEPTION 'tables before'; END IF;
  IF (SELECT count(*) FROM source_capture_ledger) <> 211 THEN RAISE EXCEPTION 'ledger before'; END IF;
  IF (SELECT count(*) FROM listings l JOIN venues v ON v.id=l.venue_id WHERE v.status='closed' AND l.published) <> 0 THEN RAISE EXCEPTION 'closed published before'; END IF;
  SELECT count(*), max(id) INTO n, aud_max FROM audit_log; IF n <> 120196 OR aud_max <> 126025 THEN RAISE EXCEPTION 'audit before % / %', n, aud_max; END IF;
  IF (SELECT count(*) FROM (SELECT 've_'||split_part(x,':',2) AS venue_id, split_part(x,':',1)::int AS rank, 'https://www.oadguides.com/lists/'||l||'/top-restaurants/2026' AS url FROM (SELECT 'europe' l, unnest(string_to_array(e,',')) x UNION ALL SELECT 'asia', unnest(string_to_array(a,',')) UNION ALL SELECT 'japan', unnest(string_to_array(j,','))) z) o JOIN venues v ON v.id=o.venue_id WHERE v.status='closed') <> 44 THEN RAISE EXCEPTION 'closed rows'; END IF;
  IF EXISTS (SELECT 1 FROM awards aw JOIN (SELECT 've_'||split_part(x,':',2) AS venue_id, split_part(x,':',1)::int AS rank, 'https://www.oadguides.com/lists/'||l||'/top-restaurants/2026' AS url FROM (SELECT 'europe' l, unnest(string_to_array(e,',')) x UNION ALL SELECT 'asia', unnest(string_to_array(a,',')) UNION ALL SELECT 'japan', unnest(string_to_array(j,','))) z) o ON o.venue_id=aw.venue_id WHERE aw.source_id='oad' AND aw.year=2026) THEN RAISE EXCEPTION 'row exists'; END IF;
  -- WRITE: awards
  SELECT max(id) INTO first_award FROM awards;
  INSERT INTO awards (venue_id, source_id, year, rank, category, distinction, source_url)
    SELECT venue_id, 'oad', 2026, rank, 'No. '||rank, NULL, url FROM (SELECT 've_'||split_part(x,':',2) AS venue_id, split_part(x,':',1)::int AS rank, 'https://www.oadguides.com/lists/'||l||'/top-restaurants/2026' AS url FROM (SELECT 'europe' l, unnest(string_to_array(e,',')) x UNION ALL SELECT 'asia', unnest(string_to_array(a,',')) UNION ALL SELECT 'japan', unnest(string_to_array(j,','))) z) p ORDER BY url, rank;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1794 THEN RAISE EXCEPTION 'insert %', n; END IF;
  -- WRITE: ledger
  INSERT INTO source_capture_ledger (publisher, field_type, items, job) VALUES
    ('oad', 'award', 695, 'cleanup:load-oad-2026-europe-asia-japan-2026-11-03 | open item 1: new OAD 2026 rows, list prints 774 | https://www.oadguides.com/lists/europe/top-restaurants/2026 | Ben Nov 3 21:16 ET "1A, 2A, 3A, 4A, 5A, 6A"'),
    ('oad', 'award', 506, 'cleanup:load-oad-2026-europe-asia-japan-2026-11-03 | open item 1: new OAD 2026 rows, list prints 590 | https://www.oadguides.com/lists/asia/top-restaurants/2026 | Ben Nov 3 21:16 ET "1A, 2A, 3A, 4A, 5A, 6A"'),
    ('oad', 'award', 593, 'cleanup:load-oad-2026-europe-asia-japan-2026-11-03 | open item 1: new OAD 2026 rows, list prints 799; No. 773 already award 32495 | https://www.oadguides.com/lists/japan/top-restaurants/2026 | Ben Nov 3 21:16 ET "1A, 2A, 3A, 4A, 5A, 6A"');
  -- POST gates
  IF (SELECT count(*) FROM awards) <> 27118 OR (SELECT count(*) FROM awards WHERE source_id='oad' AND year=2026) <> 2496 OR (SELECT count(*) FROM awards WHERE id > first_award) <> 1794 THEN RAISE EXCEPTION 'awards after'; END IF;
  SELECT md5(string_agg(venue_id||'|'||rank||'|'||source_url, E'\n' ORDER BY venue_id||'|'||rank||'|'||source_url COLLATE "C")) INTO fp FROM awards WHERE id > first_award AND source_id='oad' AND year=2026 AND category='No. '||rank AND distinction IS NULL;
  IF fp <> '4ef72925a3d80fc2292ccd9e0c620aaa' THEN RAISE EXCEPTION 'rows after %', fp; END IF;
  IF (SELECT count(*) FROM venues) <> 11336 OR (SELECT count(*) FROM venues WHERE status='closed') <> 294 OR (SELECT count(*) FROM slugs) <> 13184 OR (SELECT count(*) FROM listings) <> 11336 OR (SELECT count(*) FROM price) <> 7759 OR (SELECT sum(venues_count) FROM cities) <> 11042 THEN RAISE EXCEPTION 'tables after'; END IF;
  IF (SELECT count(*) FROM source_capture_ledger) <> 214 THEN RAISE EXCEPTION 'ledger after'; END IF;
  IF (SELECT count(*) FROM listings l JOIN venues v ON v.id=l.venue_id WHERE v.status='closed' AND l.published) <> 0 THEN RAISE EXCEPTION 'closed published after'; END IF;
  SELECT string_agg(table_name||':'||action||'='||c, ',' ORDER BY table_name COLLATE "C", action COLLATE "C") INTO s FROM (SELECT table_name, action, count(*) c FROM audit_log WHERE id > aud_max GROUP BY 1,2) z;
  IF s IS DISTINCT FROM 'awards:INSERT=1794' THEN RAISE EXCEPTION 'audit after %', s; END IF;
  RAISE NOTICE 'OK: all gates passed';
END
$load$;
COMMIT;
SELECT 'OK: all gates passed' AS result;
